from itertools import combinations

def solve_m(m):
    if m <= 0:
        return False

    total_sum = m * (m + 1) // 2
    target_sum = total_sum // 3

    # Check if the target sum is an integer
    if total_sum % 3 != 0:
        return False

    S = list(range(1, m + 1))

    # Iterate over all possible non-empty subsets X
    for k in range(1, m + 1):
        for X_tuple in combinations(S, k):
            X = set(X_tuple)
            sum_X = sum(X)

            if sum_X != target_sum:
                continue

            # Elements remaining after selecting X
            S_prime = sorted(list(set(S) - X))

            # Iterate over all possible non-empty subsets Y of S_prime
            # Note: Y must be non-empty
            for l in range(1, len(S_prime) + 1):
                for Y_tuple in combinations(S_prime, l):
                    Y = set(Y_tuple)
                    sum_Y = sum(Y)

                    if sum_Y == target_sum:
                        # Found a valid pair (X, Y). Since Y is a subset of S_prime (S \ X), 
                        # X and Y are guaranteed to be disjoint.
                        # X and Y are guaranteed to be non-empty by iteration setup.
                        return True
    return False

results = {}
for m in range(1, 11):
    results[m] = solve_m(m)

print(results)

