def solve():
    count = 0
    for m in range(1, 101):
        S = m * (m + 1) // 2
        if S % 3 != 0:
            continue
        K = S // 3

        # dp[s1][s2] = possible?
        # Since we only need to know if it's possible, we can use a set of (s1, s2)
        possible_sums = {(0, 0)}
        for i in range(1, m + 1):
            new_sums = set()
            for s1, s2 in possible_sums:
                # Option 1: i is not in X or Y
                new_sums.add((s1, s2))
                # Option 2: i is in X
                if s1 + i <= K:
                    new_sums.add((s1 + i, s2))
                # Option 3: i is in Y
                if s2 + i <= K:
                    new_sums.add((s1, s2 + i))
            possible_sums = new_sums

        if (K, K) in possible_sums:
            count += 1
            print(f"m={m} works")
        else:
            print(f"m={m} does not work")

    return count

print(solve())
